const valid = {
  event_id: 'F100-001',
  capital_tiyin: '10000000000',
  horizon_months: 12,
  effective_risk: 'moderate',
  confirmed: true,
};
const duplicate = Object.assign({}, valid);
const invalid = {
  event_id: 'F100-invalid',
  capital_tiyin: '-100',
  horizon_months: 12,
  effective_risk: 'moderate',
  confirmed: true,
};
return [valid, duplicate, invalid].map((f) => ({ json: f }));

// DEMO synthetic prices. All money is BigInt; money in JSON is strings. No parseFloat/Number for money.
const C = 10000000000n;
const BPS = 10000n;
const RISKS = ['conservative', 'moderate', 'aggressive'];
const MONEY_RE = /^(0|[1-9][0-9]*)$/;

function validate(e) {
  const errs = [];
  if (typeof e.event_id !== 'string' || e.event_id.trim() === '') errs.push('event_id');
  if (typeof e.capital_tiyin !== 'string' || !MONEY_RE.test(e.capital_tiyin) || BigInt(e.capital_tiyin) <= 0n) errs.push('capital_tiyin');
  if (typeof e.horizon_months !== 'number' || !Number.isInteger(e.horizon_months) || e.horizon_months < 1) errs.push('horizon_months');
  if (!RISKS.includes(e.effective_risk)) errs.push('effective_risk');
  if (e.confirmed !== true) errs.push('confirmed');
  return errs;
}

function fmtBtc(n) {
  const s = n.toString().padStart(9, '0');
  return s.slice(0, s.length - 8) + '.' + s.slice(-8);
}

function calculate() {
  const targets = { deposit: 6000n, gold: 2500n, btc: 1500n };
  const budget = {
    deposit: (C * targets.deposit) / BPS,
    gold: (C * targets.gold) / BPS,
    btc: (C * targets.btc) / BPS,
  };

  // Deposit
  const depositCost = 6000000000n;
  const depositFee = 0n;

  // Gold: whole bars, max weight within budget, then min cost, then min bar count
  const barDefs = [
    { g: 5n, cost: 575000000n },
    { g: 10n, cost: 1150000000n },
    { g: 20n, cost: 2300000000n },
  ];
  let best = null;
  for (let a = 0n; a * barDefs[0].cost <= budget.gold; a++) {
    for (let b = 0n; a * barDefs[0].cost + b * barDefs[1].cost <= budget.gold; b++) {
      for (let c = 0n; a * barDefs[0].cost + b * barDefs[1].cost + c * barDefs[2].cost <= budget.gold; c++) {
        const cost = a * barDefs[0].cost + b * barDefs[1].cost + c * barDefs[2].cost;
        const weight = a * barDefs[0].g + b * barDefs[1].g + c * barDefs[2].g;
        const count = a + b + c;
        const cand = { a, b, c, cost, weight, count };
        if (
          best === null ||
          cand.weight > best.weight ||
          (cand.weight === best.weight && cand.cost < best.cost) ||
          (cand.weight === best.weight && cand.cost === best.cost && cand.count < best.count)
        ) {
          best = cand;
        }
      }
    }
  }
  const goldCost = best.cost;

  // BTC: step 0.00000001 BTC costs 1000 tiyin, fee 1% rounded up, min notional 100000 UZS = 10000000 tiyin
  const STEP_COST = 1000n;
  const MIN_NOTIONAL = 10000000n;
  const feeOf = (cost) => (cost + 99n) / 100n;
  const total = (n) => n * STEP_COST + feeOf(n * STEP_COST);
  let steps = (budget.btc * 100n) / (101n * STEP_COST);
  while (total(steps + 1n) <= budget.btc) steps += 1n;
  while (steps > 0n && total(steps) > budget.btc) steps -= 1n;
  if (steps * STEP_COST < MIN_NOTIONAL) steps = 0n;
  const btcCost = steps * STEP_COST;
  const btcFee = feeOf(btcCost);
  const nextCost = (steps + 1n) * STEP_COST;
  const nextFee = feeOf(nextCost);

  const totalFee = depositFee + btcFee;
  const cash = C - depositCost - goldCost - btcCost - btcFee;
  const balanceOk = depositCost + goldCost + btcCost + btcFee + cash === C;
  const capsOk =
    (depositCost + depositFee) * BPS <= C * targets.deposit &&
    goldCost * BPS <= C * targets.gold &&
    (btcCost + btcFee) * BPS <= C * targets.btc;

  // Display net cost shares
  const D = C - totalFee;
  const nums = [
    { id: 'btc', num: btcCost },
    { id: 'cash', num: cash },
    { id: 'deposit', num: depositCost },
    { id: 'gold', num: goldCost },
  ];
  const rows = nums.map((r) => ({
    id: r.id,
    bps: (r.num * BPS) / D,
    rem: (r.num * BPS) % D,
  }));
  let missing = Number(BPS - rows.reduce((s, r) => s + r.bps, 0n));
  const order = rows.slice().sort((x, y) => {
    if (x.rem !== y.rem) return x.rem > y.rem ? -1 : 1;
    return x.id < y.id ? -1 : 1;
  });
  for (let i = 0; i < missing; i++) order[i].bps += 1n;
  const display = {};
  rows.forEach((r) => { display[r.id] = Number(r.bps); });
  display.total = Number(rows.reduce((s, r) => s + r.bps, 0n));

  return {
    capital_tiyin: C.toString(),
    targets_bps: { deposit: 6000, gold: 2500, btc: 1500 },
    budgets_tiyin: {
      deposit: budget.deposit.toString(),
      gold: budget.gold.toString(),
      btc: budget.btc.toString(),
    },
    deposit: { cost_tiyin: depositCost.toString(), fee_tiyin: depositFee.toString() },
    gold: {
      bars_5g: Number(best.a),
      bars_10g: Number(best.b),
      bars_20g: Number(best.c),
      grams: Number(best.weight),
      cost_tiyin: goldCost.toString(),
      fee_tiyin: '0',
    },
    btc: {
      quantity_btc: fmtBtc(steps),
      steps: steps.toString(),
      cost_tiyin: btcCost.toString(),
      fee_tiyin: btcFee.toString(),
      next_step: {
        quantity_btc: fmtBtc(steps + 1n),
        cost_tiyin: nextCost.toString(),
        fee_tiyin: nextFee.toString(),
        total_tiyin: (nextCost + nextFee).toString(),
        exceeds_budget: nextCost + nextFee > budget.btc,
      },
    },
    cash_tiyin: cash.toString(),
    total_fee_tiyin: totalFee.toString(),
    balance_ok: balanceOk,
    hard_caps_ok: capsOk,
    display_bps: display,
  };
}

// Deduplication is only inside this batch (Set). NOT durable idempotency.
const seen = new Set();
const out = [];
for (const item of $input.all()) {
  const e = item.json;
  const errs = validate(e);
  if (errs.length > 0) {
    out.push({ json: { event_id: e.event_id, status: 'rejected', reason_code: 'VALIDATION_ERROR', invalid_fields: errs } });
    continue;
  }
  if (seen.has(e.event_id)) {
    out.push({ json: { event_id: e.event_id, status: 'duplicate', reason_code: 'DUPLICATE_IN_BATCH' } });
    continue;
  }
  seen.add(e.event_id);
  const supported = e.capital_tiyin === '10000000000' && e.horizon_months === 12 && e.effective_risk === 'moderate';
  if (!supported) {
    out.push({ json: { event_id: e.event_id, status: 'rejected', reason_code: 'UNSUPPORTED_DEMO_PROFILE' } });
    continue;
  }
  out.push({ json: { event_id: e.event_id, status: 'accepted', allocation: calculate() } });
}
return out;

const items = $input.all().map((i) => i.json);
const failures = [];
function check(cond, msg) { if (!cond) failures.push(msg); }

const counts = { accepted: 0, duplicate: 0, rejected: 0 };
for (const r of items) {
  if (counts[r.status] !== undefined) counts[r.status] += 1;
}
check(items.length === 3, 'expected 3 items, got ' + items.length);
check(counts.accepted === 1, 'accepted count ' + counts.accepted);
check(counts.duplicate === 1, 'duplicate count ' + counts.duplicate);
check(counts.rejected === 1, 'rejected count ' + counts.rejected);

const rej = items.find((r) => r.status === 'rejected');
check(rej && rej.reason_code === 'VALIDATION_ERROR' && rej.event_id === 'F100-invalid', 'rejected must be F100-invalid / VALIDATION_ERROR');
const dup = items.find((r) => r.status === 'duplicate');
check(dup && dup.event_id === 'F100-001', 'duplicate must be F100-001');

const acc = items.find((r) => r.status === 'accepted');
const a = acc ? acc.allocation : null;
if (!a) {
  failures.push('no accepted allocation');
} else {
  check(a.deposit.cost_tiyin === '6000000000', 'deposit cost ' + a.deposit.cost_tiyin);
  check(a.gold.cost_tiyin === '2300000000', 'gold cost ' + a.gold.cost_tiyin);
  check(a.gold.bars_20g === 1 && a.gold.bars_10g === 0 && a.gold.bars_5g === 0, 'gold must be one 20g bar');
  check(a.btc.quantity_btc === '0.01485148', 'btc quantity ' + a.btc.quantity_btc);
  check(a.btc.cost_tiyin === '1485148000', 'btc cost ' + a.btc.cost_tiyin);
  check(a.btc.fee_tiyin === '14851480', 'btc fee ' + a.btc.fee_tiyin);
  check(a.cash_tiyin === '200000520', 'cash ' + a.cash_tiyin);
  const sum = BigInt(a.deposit.cost_tiyin) + BigInt(a.deposit.fee_tiyin) + BigInt(a.gold.cost_tiyin) + BigInt(a.gold.fee_tiyin) + BigInt(a.btc.cost_tiyin) + BigInt(a.btc.fee_tiyin) + BigInt(a.cash_tiyin);
  check(sum === 10000000000n, 'balance sum ' + sum.toString());
  check(a.balance_ok === true, 'balance_ok flag');
  check(a.hard_caps_ok === true, 'hard_caps_ok flag');
  const budgetBtc = BigInt(a.budgets_tiyin.btc);
  const btcTotal = BigInt(a.btc.cost_tiyin) + BigInt(a.btc.fee_tiyin);
  check(btcTotal <= budgetBtc, 'btc cost+fee exceeds budget');
  check(a.btc.next_step.exceeds_budget === true, 'next step flag');
  check(BigInt(a.btc.next_step.total_tiyin) > budgetBtc, 'next step must exceed budget: ' + a.btc.next_step.total_tiyin);
  check(a.btc.next_step.quantity_btc === '0.01485149', 'next step quantity ' + a.btc.next_step.quantity_btc);
  const d = a.display_bps;
  check(d.deposit === 6009 && d.gold === 2304 && d.btc === 1487 && d.cash === 200 && d.total === 10000, 'display bps ' + JSON.stringify(d));
}

if (failures.length > 0) {
  throw new Error('F100 assertions failed: ' + failures.join('; '));
}
return [{ json: { tests_passed: true, counts, allocation: a } }];
